import{_ as p,a0 as l,w as o,s as d,ao as u,I as n,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何在 Linux 中禁用內置攝像頭 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中禁用內置攝像頭 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中禁用內置攝像頭 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中禁用內置攝像頭 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180531 How To Disable Built-in Webcam In Linux","title":"如何在 Linux 中禁用內置攝像頭","tag":"201806","desc":""},"relativePath":"201806/20180531 How To Disable Built-in Webcam In Linux.md","filePath":"[post].md"}'),r={name:"201806/20180531 How To Disable Built-in Webcam In Linux.md"};function h(b,s,c,g,k,m){const e=l("Link");return o(),d("div",null,[s[15]||(s[15]=u(`<h1 id="如何在-linux-中禁用內置攝像頭" tabindex="-1">如何在 Linux 中禁用內置攝像頭 <a class="header-anchor" href="#如何在-linux-中禁用內置攝像頭" aria-label="Permalink to “如何在 Linux 中禁用內置攝像頭”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2015/08/webcam-2-720x340.jpg" alt=""></p><p>今天，我們將看到如何禁用未使用的內置網絡攝像頭或外置攝像頭，以及如何在 Linux 中需要時啓用它。禁用網絡攝像頭可以在很多方面為你提供幫助。你可以防止惡意軟件控制你的集成攝像頭，並監視你和你的家庭。我們已經閲讀過無數的故事，一些黑客可以在你不知情的情況下使用你的攝像頭監視你。通過黑客攻擊你的網絡攝像頭，用户可以在線共享你的私人照片和視頻。可能有很多原因。如果你想知道如何禁用筆記本電腦或台式機中的網絡攝像頭，那麼你很幸運。這個簡短的教程將告訴你如何做。請繼續閲讀。</p><p>我在 Arch Linux 和 Ubuntu 上測試了這個指南。它的工作原理如下所述。我希望這也可以用在其他 Linux 發行版上。</p><h3 id="在-linux-中禁用內置攝像頭" tabindex="-1">在 Linux 中禁用內置攝像頭 <a class="header-anchor" href="#在-linux-中禁用內置攝像頭" aria-label="Permalink to “在 Linux 中禁用內置攝像頭”">​</a></h3><p>首先，使用如下命令找到網絡攝像頭驅動：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo lsmod | grep uvcvideo</span></span></code></pre></div><p>示例輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uvcvideo 114688 1</span></span>
<span class="line"><span>videobuf2_vmalloc 16384 1 uvcvideo</span></span>
<span class="line"><span>videobuf2_v4l2 28672 1 uvcvideo</span></span>
<span class="line"><span>videobuf2_common 53248 2 uvcvideo,videobuf2_v4l2</span></span>
<span class="line"><span>videodev 208896 4 uvcvideo,videobuf2_common,videobuf2_v4l2</span></span>
<span class="line"><span>media 45056 2 uvcvideo,videodev</span></span>
<span class="line"><span>usbcore 286720 9 uvcvideo,usbhid,usb_storage,ehci_hcd,ath3k,btusb,uas,ums_realtek,ehci_pci</span></span></code></pre></div><p>這裏，<strong>uvcvideo</strong> 是我的網絡攝像頭驅動。</p><p>現在，讓我們禁用網絡攝像頭。</p><p>為此，請編輯以下文件（如果文件不存在，只需創建它）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/modprobe.d/blacklist.conf</span></span></code></pre></div><p>添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>##Disable webcam.</span></span>
<span class="line"><span>blacklist uvcvideo</span></span></code></pre></div><p><code>##Disable webcam</code> 這行不是必需的。為了便於理解，我添加了它。</p><p>保存並退出文件。重啓系統以使更改生效。</p><p>要驗證網絡攝像頭是否真的被禁用，請打開任何即時通訊程序或網絡攝像頭軟件，如 Cheese 或 Guvcview。你會看到如下的空白屏幕。</p><p>Cheese 輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2015/08/cheese.jpg" alt=""></p><p>Guvcview 輸出：</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2015/08/guvcview.jpg" alt=""></p><p>看見了麼？網絡攝像頭被禁用而無法使用。</p><p>要啓用它，請編輯：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nano /etc/modprobe.d/blacklist.conf</span></span></code></pre></div><p>註釋掉你之前添加的行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>##Disable webcam.</span></span>
<span class="line"><span>#blacklist uvcvideo</span></span></code></pre></div><p>保存並關閉文件。然後，重啓計算機以啓用網絡攝像頭。</p><p>這樣夠了嗎？不。為什麼？如果有人可以遠程訪問你的系統，他們可以輕鬆啓用網絡攝像頭。所以，在不使用時用膠帶覆蓋它或者拔掉相機或者在 BIOS 中禁用它是一個不錯的主意。此方法不僅用於禁用內置攝像頭，還用於外部網絡攝像頭。</p><p>就是這些了。希望對你有用。還有更好的東西。敬請關注！</p><p>乾杯!</p><hr>`,32)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-disable-built-in-webcam-in-ubuntu/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-disable-built-in-webcam-in-ubuntu/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 譯者：",-1)),a(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[i("Linux中國",-1)])]),_:1}),s[14]||(s[14]=i(" 榮譽推出",-1))])])}const w=p(r,[["render",h]]);export{x as __pageData,w as default};
